 if(!state.over){let energy=3;for(let i=0;i<2;i++){const options=['soldier','archer','guard'].filter(t=>TYPES[t].cost<=energy);if(!options.length)break;const type=(i===0&&Math.random()<.28?'guard':i===1&&Math.random()<.35?'archer':'soldier');if(TYPES[type].cost>energy)continue;const spots=[];for(let y=1;y<=3;y++)for(let x=0;x<SIZE;x++)if(!unitAt(x,y)&&!coreAt(x,y))spots.push({x,y});if(!spots.length)break;const spot=spots.sort((a,b)=>distance(a,CORE.me)-distance(b,CORE.me))[0];spawn('ai',type,spot.x,spot.y);energy-=TYPES[type].cost;addLog(`상대가 ${TYPES[type].name}을(를) 배치했다.`)}}
