 board.append(p)}
 renderStats();document.querySelectorAll('.card').forEach(b=>{b.classList.toggle('active',state.mode===b.dataset.action);b.disabled=state.over||state.acting||state.energy<(TYPES[b.dataset.action]?.cost||2)});document.getElementById('endTurn').disabled=state.over||state.acting;logEl.innerHTML=state.log.map(t=>`<div class="log-item"><span class="log-bullet">✦</span><span>${t}</span></div>`).join('')}
