function showModal(kind){const root=document.getElementById('modalRoot');let title='',body='',icon='';if(kind==='intro'){title='돌의 전장에 오신 걸 환영합니다';icon='◉';body='바둑판 위에서 돌을 소환하고, 적의 핵심돌을 무너뜨리세요. 매 턴 기력 3을 얻습니다. 아군 돌로 적을 공격하거나 전술 카드로 전세를 뒤집으세요.'}else if(kind==='rules'){title='전투 방법';icon='✦';body='① 전술 카드를 고르고 빛나는 교차점에 돌을 배치합니다.\n② 아군 돌을 누르고 사거리 안의 적을 눌러 공격합니다.\n③ 전사돌은 사거리 1, 궁수돌은 사거리 2, 수호돌은 체력이 높습니다.\n④ 기력 폭발은 기력 2를 써서 적 또는 상대 핵심돌에 피해 2를 줍니다.\n⑤ 턴마다 기력 3을 회복하며, 적 핵심돌 체력을 0으로 만들면 승리!'}else if(kind==='win'){title='승리! 전장의 주인이 되었습니다';icon='🏆';body='상대 핵심돌이 무너졌습니다. 훌륭한 전략이었어요! 새 게임에서 다시 도전할 수 있습니다.'}else{title='패배… 핵심돌이 무너졌습니다';icon='🪨';body='내 핵심돌이 파괴되었습니다. 배치와 공격 순서를 바꿔 다시 도전해보세요!'}root.innerHTML=`<div class="overlay"><div class="modal"><div class="modal-emblem">${icon}</div><h1>${title}</h1><p>${body.replaceAll('\n','<br>')}</p><button class="end-turn" id="modalPrimary">${kind==='intro'||kind==='rules'?'전장으로':'다시 시작'}　→</button>${kind==='intro'?'<button class="secondary" id="modalRules">규칙 먼저 읽기</button>':''}</div></div>`;document.getElementById('modalPrimary').onclick=()=>{root.innerHTML='';if(kind==='win'||kind==='lose')init()};const rules=document.getElementById('modalRules');if(rules)rules.onclick=()=>showModal('rules')}
let toastTimer;function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),1900)}
document.getElementById('rulesBtn').onclick=()=>showModal('rules');document.getElementById('restartBtn').onclick=()=>{if(confirm('새 게임을 시작할까요? 현재 전투는 종료됩니다.'))init()};
init();
</script>
</body>
</html>

